function myMap(array, callback, thisArg) {
  if (array == null) throw new TypeError('array is null or undefined');
  if (typeof callback !== 'function') throw new TypeError('callback is not a function');

  const O = Object(array);
  const len = O.length >>> 0;
  const A = new Array(len);

  for (let k = 0; k < len; k++) {
    if (k in O) {
      A[k] = callback.call(thisArg, O[k], k, O);
    }
  }
  return A;
}

myMap([1, 2, 3], n => n * 2); // [2,4,6]

function myFilter(array, predicate, thisArg) {
  const O = Object(array);
  const len = O.length >>> 0;
  const result = [];

  for (let k = 0; k < len; k++) {
    if (k in O && predicate.call(thisArg, O[k], k, O)) {
      result.push(O[k]);
    }
  }
  return result;
}

function flatten(input, depth = 1) {
  const out = [];
  for (const item of input) {
    if (Array.isArray(item) && depth > 0) {
      out.push(...flatten(item, depth - 1));
    } else {
      out.push(item);
    }
  }
  return out;
}

flatten([1, [2, [3]]], Infinity); // [1,2,3]

